insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  20,
  $wyb$A batch processor that reads a folder of CV PDFs, sends each one alongside your job description to the AI for scoring on skills match, experience, culture fit, and growth trajectory, then writes structured results -- score, strengths, gaps, recommendation -- into an Airtable base sorted by score. A consistency guard flags any candidate whose overall_score doesn't actually follow from its four component scores, and an optional blind-review mode redacts common identity signals before scoring.$wyb$,
  $wyl$[
  "Write a rubric-based job description that gives the AI clear, explicit scoring criteria",
  "Parse a structured scoring reply defensively, stripping a code fence the AI wasn't supposed to add",
  "Sanity-check an aggregate score against the components it's meant to summarize, not just trust it",
  "Extract just the fields you need (name, email) from the top of a document to save tokens",
  "Write records to Airtable via its REST API, respecting its rate limit",
  "Build an optional bias-reduction 'blind review' mode with real, tested regex redaction"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "135 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your AI Builder key (Credits page on your dashboard)",
    "Python 3.10+ installed",
    "A free Airtable account",
    "3-5 sample CV PDFs (anonymized or your own past resumes work fine for testing)"
  ],
  "outcomes": [
    "Write a rubric-based job description that gives the AI clear scoring criteria",
    "Extract text from a folder of CV PDFs in bulk, skipping any that fail to read",
    "Score each candidate 1-10 across 4 dimensions, with a guard that catches an overall_score that doesn't follow from them",
    "Push ranked results into an Airtable recruitment tracker",
    "Run an optional bias-reduction blind review mode with real, tested redaction logic"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Write your JD rubric and set up Airtable",
      "time": "30 min",
      "description": "The scoring is only as good as the rubric you give the AI.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> uses YOUR OWN free Google Gemini API key\n  AI_PROVIDER=credits   -> uses your AI Builder credits from this course\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: your own free Gemini key (recommended, no course\ncredits spent):\n\n  1. Go to https://aistudio.google.com/apikey and click \"Create API key\"\n     (needs a free Google account, no credit card)\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: your AI Builder credits from this course:\n\n  1. Open your dashboard on socialdevtechnologies.com\n  2. Go to Credits, and click \"Copy my AI Builder key\"\n  3. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=credits\n         SDT_API_KEY=sdt_live_paste_your_own_key_here\n\nNever share either key or put it on GitHub. Each one spends YOUR\nquota - Gemini's free tier, or your course credits.\n\nThat's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\nGEMINI_MODEL = \"gemini-3.6-flash\"\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\n# Where AI Builder credit requests go. This is Social Dev's server, not\n# an AI company's - it checks your credits, then talks to Claude for you.\nGATEWAY_URL = \"https://qkrfpuckvymjpewcszgs.supabase.co/functions/v1/ai-gateway\"\n\n# This one is safe to have in the code - it is a public key that only\n# identifies the Social Dev project, not you. Your personal key is the\n# one in .env.\nPUBLIC_PROJECT_KEY = (\n    \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.\"\n    \"eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrcmZwdWNrdnltanBld2NzemdzIiwicm9sZSI6ImFub24i\"\n    \"LCJpYXQiOjE3ODExMDk1MTQsImV4cCI6MjA5NjY4NTUxNH0.\"\n    \"Pv8MYd0zAQyk7tiConCLSUindSpMS83r4lY8dFU_5yE\"\n)\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"credits\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"SDT_API_KEY\"):\n        return \"credits\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=credits\\n\"\n        \"    SDT_API_KEY=sdt_live_paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    try:\n        response = requests.post(\n            GEMINI_URL,\n            params={\"key\": api_key},\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\n            \"Could not reach Gemini. Check your internet connection and try again.\"\n        )\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Gemini (status {response.status_code}).\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    candidates = data.get(\"candidates\") or []\n    if not candidates:\n        raise AIError(\n            \"Gemini returned no candidates - this usually means the prompt \"\n            \"tripped a safety filter. Try rephrasing it.\"\n        )\n\n    candidate = candidates[0]\n    parts = candidate.get(\"content\", {}).get(\"parts\", [])\n    text = \"\".join(part.get(\"text\", \"\") for part in parts)\n\n    if not text and candidate.get(\"finishReason\") == \"MAX_TOKENS\":\n        raise AIError(\n            \"Gemini ran out of room before finishing its answer. Raise \"\n            \"max_tokens and try again.\"\n        )\n\n    usage = data.get(\"usageMetadata\", {})\n    return {\n        \"text\": text,\n        \"credits_charged\": None,\n        \"input_tokens\": usage.get(\"promptTokenCount\"),\n        \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n    }\n\n\ndef _ask_credits(prompt, system=None, max_tokens=1000, project=None):\n    api_key = os.environ.get(\"SDT_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to credits but no SDT_API_KEY was found.\\n\"\n            \"Copy your key from the Credits page on your dashboard and add \"\n            \"it to .env:\\n\"\n            \"    SDT_API_KEY=sdt_live_paste_your_own_key_here\"\n        )\n\n    payload = {\"prompt\": prompt, \"max_tokens\": max_tokens}\n    if system:\n        payload[\"system\"] = system\n    if project:\n        payload[\"project\"] = project\n\n    try:\n        response = requests.post(\n            GATEWAY_URL,\n            headers={\n                \"Authorization\": f\"Bearer {PUBLIC_PROJECT_KEY}\",\n                \"X-SDT-Key\": api_key,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\n            \"Could not reach the AI server. Check your internet connection \"\n            \"and try again. You were not charged any credits.\"\n        )\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from the AI server (status {response.status_code}).\")\n\n    # The server explains problems in plain English - show that message as-is\n    # rather than a status code, because it is written to be read by you.\n    if \"error\" in data:\n        raise AIError(data[\"error\"])\n\n    return data\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict. When you're on\n    AI_PROVIDER=credits, result[\"credits_charged\"] tells you the cost; on\n    AI_PROVIDER=gemini it's always None since Gemini's free tier has no\n    per-request credit cost.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_credits(prompt, system=system, max_tokens=max_tokens, project=project)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - optional label, only used on AI_PROVIDER=credits, so you can\n                  see usage per project later.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        if result[\"credits_charged\"] is not None:\n            print(\"Credits used:\", result[\"credits_charged\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no course credits spent)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: this course's AI Builder credits (comment OPTION 1 out above,\n# uncomment these two lines instead)\n# Get yours from your dashboard: Credits -> Copy my AI Builder key\n# AI_PROVIDER=credits\n# SDT_API_KEY=sdt_live_paste_your_own_key_here\n\n# Airtable - get your Base ID and API key from Airtable's developer docs\nAIRTABLE_BASE_ID=paste_your_base_id_here\nAIRTABLE_API_KEY=paste_your_api_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `jd.txt` with: Role title, Required skills/experience, Nice-to-haves, and an explicit \"Red flags\" section (e.g. \"no evidence of production ownership\", \"frequent <1yr job hops without explanation\"). Red flags matter - without them, scores tend to cluster too high.",
          "verify": "Show your jd.txt to a colleague and ask if they'd score a hypothetical candidate the same way - if your red flags are too vague, sharpen them now."
        },
        {
          "instruction": "In Airtable, create a base with a \"Candidates\" table containing fields: Name (text), Email (text), Score (number), Strengths (long text), Gaps (long text), Recommendation (single select: Strong Yes/Yes/Maybe/No). Create a view sorted by Score descending.",
          "verify": "Confirm your Candidates table has all 6 fields with the right types - Score must be a number field for sorting to work correctly later."
        },
        {
          "instruction": "Put 3-5 sample CV PDFs into a `cvs/` folder.",
          "verify": "Open each PDF and confirm the text is actually selectable/searchable (not a scanned image) - a scanned CV has no embedded text for PyPDF2 to extract."
        }
      ],
      "goFurther": "Deliberately write jd.txt for a role very different from any of your sample CVs, and note your own prediction of how each candidate should score - you'll compare this to the AI's actual scores in Build 2."
    },
    {
      "number": 2,
      "title": "Extract CVs and build the scorer",
      "time": "45 min",
      "description": "This is the core: turning a CV and a job description into a structured score. The safety guard here checks that the overall_score actually follows from the four dimension scores it's supposed to summarize, instead of trusting it blindly.",
      "steps": [
        {
          "instruction": "Create `cv_reader.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 1) - extracts text\nfrom every CV PDF in a folder.\n\"\"\"\n\nimport os\n\nfrom PyPDF2 import PdfReader\n\n\ndef read_cvs(folder=\"cvs\"):\n    \"\"\"\n    Reads every .pdf file in folder and returns {path: extracted_text}.\n\n        cvs = read_cvs(\"cvs\")\n\n    Skips any file that isn't a .pdf, and skips (with a printed warning,\n    not a crash) any PDF that fails to extract at all - a single\n    corrupted file in a folder of 20 CVs shouldn't stop the other 19\n    from being screened.\n    \"\"\"\n    texts = {}\n    for filename in sorted(os.listdir(folder)):\n        if not filename.lower().endswith(\".pdf\"):\n            continue\n        path = os.path.join(folder, filename)\n        try:\n            reader = PdfReader(path)\n            texts[path] = \"\\n\".join(page.extract_text() or \"\" for page in reader.pages)\n        except Exception as problem:\n            print(f\"Skipped {filename}: could not read as a PDF ({problem})\")\n    return texts\n\n\nif __name__ == \"__main__\":\n    print(\"This file only wraps real PDF reads from disk - there's no\")\n    print(\"offline self-test here. It's exercised for real in Build 3's batch.py,\")\n    print(\"once you have real CV PDFs in your cvs/ folder.\")\n",
          "verify": "This file only wraps real PDF reads - there's no offline self-test to run here."
        },
        {
          "instruction": "Create `score.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 2).\n\nTurns a CV and a job description into a structured, 1-10 score across\nfour dimensions. The JSON parsing is defensive (a stray code fence is\nstripped, not fatal), and this project's safety guard checks that\noverall_score is actually consistent with the four dimension scores\nit's supposed to summarize - not just any number 1-10 the AI feels like.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\nSCORE_FIELDS = [\"skills_match\", \"experience_level\", \"culture_fit\", \"growth_trajectory\", \"overall_score\"]\nVALID_RECOMMENDATIONS = {\"Strong Yes\", \"Yes\", \"Maybe\", \"No\"}\n\n# How far overall_score is allowed to drift from the average of the 4\n# dimension scores before this project flags it for manual review. A\n# real LLM failure mode: it reasons carefully about each dimension, then\n# writes an overall_score that doesn't actually follow from them (e.g.\n# all four dimensions score 4-5, but overall_score comes back as 9).\nMAX_OVERALL_SCORE_DRIFT = 3\n\nMAX_CV_CHARACTERS = 6000\n\n\ndef build_prompt(cv_text, jd_text):\n    trimmed = cv_text[:MAX_CV_CHARACTERS]\n    return f\"\"\"Job description:\n{jd_text}\n\nCandidate CV:\n{trimmed}\n\nScore the candidate 1-10 on each of: skills_match, experience_level,\nculture_fit, growth_trajectory. Then give an overall_score (1-10) that\nshould be roughly consistent with those four - not a separate,\nunrelated judgment.\n\nAlso give top 3 strengths, top 2 gaps (as arrays of strings), and a\nrecommendation - exactly one of: \"Strong Yes\", \"Yes\", \"Maybe\", \"No\".\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"skills_match\": 0, \"experience_level\": 0, \"culture_fit\": 0, \"growth_trajectory\": 0,\n\"overall_score\": 0, \"strengths\": [\"...\", \"...\", \"...\"], \"gaps\": [\"...\", \"...\"],\n\"recommendation\": \"...\"}}\"\"\"\n\n\ndef parse_score_reply(reply):\n    \"\"\"\n    Turns the AI's reply into a dict, tolerating a ```json code fence.\n    Returns None (never raises) if the reply isn't valid JSON at all.\n    \"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        return json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n\ndef validate_score(data):\n    \"\"\"\n    Checks the parsed score data for two things: every required field\n    is present and numerically in range, and overall_score is actually\n    consistent with the four dimension scores it's meant to summarize.\n\n    Mutates and returns data with an extra \"needs_review\" field (and a\n    \"review_reason\" if True) - this NEVER changes overall_score itself,\n    it only flags a suspicious one for a human to double check, the same\n    \"flag, don't silently fix\" pattern used throughout this course.\n    \"\"\"\n    missing = [f for f in SCORE_FIELDS if not isinstance(data.get(f), (int, float))]\n    if missing:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Missing or non-numeric field(s): {', '.join(missing)}\"\n        return data\n\n    out_of_range = [f for f in SCORE_FIELDS if not (1 <= data[f] <= 10)]\n    if out_of_range:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Field(s) outside the 1-10 range: {', '.join(out_of_range)}\"\n        return data\n\n    dimension_scores = [data[f] for f in SCORE_FIELDS if f != \"overall_score\"]\n    average = sum(dimension_scores) / len(dimension_scores)\n    drift = abs(data[\"overall_score\"] - average)\n\n    if drift > MAX_OVERALL_SCORE_DRIFT:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = (\n            f\"overall_score ({data['overall_score']}) is {drift:.1f} points away from \"\n            f\"the average of the four dimension scores ({average:.1f}) - check whether \"\n            f\"either number actually reflects the CV.\"\n        )\n        return data\n\n    if data.get(\"recommendation\") not in VALID_RECOMMENDATIONS:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Unrecognised recommendation: {data.get('recommendation')!r}\"\n        return data\n\n    data[\"needs_review\"] = False\n    data[\"review_reason\"] = \"\"\n    return data\n\n\ndef score_candidate(cv_text, jd_text):\n    \"\"\"\n    The main function. Give it CV text and a job description, get back\n    the validated score dict.\n    \"\"\"\n    prompt = build_prompt(cv_text, jd_text)\n    reply = ask_ai(prompt, max_tokens=600, project=\"hr-recruitment-screening-agent\")\n\n    data = parse_score_reply(reply)\n    if data is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return validate_score(data)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the consistency\n    # guard work - no AI call, no credits spent:  python score.py\n\n    print(\"Checking a well-formed, internally consistent score...\")\n    good = {\n        \"skills_match\": 8, \"experience_level\": 7, \"culture_fit\": 7, \"growth_trajectory\": 8,\n        \"overall_score\": 7, \"strengths\": [\"a\", \"b\", \"c\"], \"gaps\": [\"x\", \"y\"],\n        \"recommendation\": \"Yes\",\n    }\n    result = validate_score(dict(good))\n    assert result[\"needs_review\"] is False\n    print(\"  OK - needs_review is False\")\n\n    print(\"\\nChecking a score where overall_score doesn't match the dimensions at all...\")\n    inconsistent = dict(good)\n    inconsistent[\"overall_score\"] = 2\n    result = validate_score(inconsistent)\n    assert result[\"needs_review\"] is True\n    assert \"overall_score\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking a score with a field out of the 1-10 range...\")\n    out_of_range = dict(good)\n    out_of_range[\"skills_match\"] = 15\n    result = validate_score(out_of_range)\n    assert result[\"needs_review\"] is True\n    assert \"skills_match\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking a score with a missing field entirely...\")\n    missing_field = dict(good)\n    del missing_field[\"culture_fit\"]\n    result = validate_score(missing_field)\n    assert result[\"needs_review\"] is True\n    assert \"culture_fit\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking an unrecognised recommendation string...\")\n    bad_recommendation = dict(good)\n    bad_recommendation[\"recommendation\"] = \"Definitely hire!!\"\n    result = validate_score(bad_recommendation)\n    assert result[\"needs_review\"] is True\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking parse_score_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"overall_score\": 7}\\n```'\n    assert parse_score_reply(fenced) == {\"overall_score\": 7}\n    print(\"  OK\")\n\n    print(\"\\nChecking a non-JSON reply returns None instead of crashing...\")\n    assert parse_score_reply(\"Sorry, I can't score that.\") is None\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python score.py` (no AI call, no credits spent - this only tests parsing and the consistency guard against fake data). You should see a consistent score correctly pass, an overall_score wildly out of line with its dimensions correctly flagged, an out-of-range field correctly flagged, a missing field correctly flagged, an unrecognised recommendation correctly flagged, a ```json fence correctly stripped, and a non-JSON reply correctly returning None - ending with `All checks passed.`"
        },
        {
          "instruction": "Now score one real CV against your jd.txt:",
          "prompt": "python -c \"from cv_reader import read_cvs; from score import score_candidate; cvs = read_cvs(); path, text = next(iter(cvs.items())); import json; print(json.dumps(score_candidate(text, open('jd.txt').read()), indent=2))\"",
          "verify": "You should get back a JSON object with all the scoring fields filled in with sensible values, and the strengths/gaps should reference things actually in that CV, not generic statements. needs_review should be False for a normal, consistent score."
        },
        {
          "instruction": "Create `extract_contact.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 3) - pulls just the\ncandidate's name and email from the top of their CV, using far fewer\ntokens than sending the whole document.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\n# Only the first N characters go into this call. A MONEY decision: a\n# name and email address appear in the first few lines of virtually\n# every CV ever formatted - sending the whole multi-page document to\n# extract two short fields would be paying for content this call never\n# needs to read.\nMAX_HEADER_CHARACTERS = 1000\n\n\ndef build_prompt(cv_text):\n    header = cv_text[:MAX_HEADER_CHARACTERS]\n    return f\"\"\"Extract the candidate's full name and email address from this CV\nexcerpt. Return ONLY this JSON shape, no markdown code fence:\n{{\"name\": \"...\", \"email\": \"...\"}}\n\nIf either isn't findable in this excerpt, use an empty string \"\" - do\nnot guess a plausible-looking name or email.\n\nCV EXCERPT:\n{header}\"\"\"\n\n\ndef parse_contact_reply(reply):\n    \"\"\"Same defensive JSON parsing as score.py - tolerates a code fence, returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        data = json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n    return {\"name\": data.get(\"name\", \"\"), \"email\": data.get(\"email\", \"\")}\n\n\ndef extract_contact(cv_text):\n    \"\"\"The main function. Give it CV text, get back {\"name\": \"...\", \"email\": \"...\"}.\"\"\"\n    prompt = build_prompt(cv_text)\n    reply = ask_ai(prompt, max_tokens=100, project=\"hr-recruitment-screening-agent\")\n\n    contact = parse_contact_reply(reply)\n    if contact is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\"\n        )\n    return contact\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no AI call,\n    # no credits spent:  python extract_contact.py\n    print(\"Checking a clean reply...\")\n    clean = '{\"name\": \"Amaka Obi\", \"email\": \"amaka@example.com\"}'\n    assert parse_contact_reply(clean) == {\"name\": \"Amaka Obi\", \"email\": \"amaka@example.com\"}\n    print(\"  OK\")\n\n    print(\"\\nChecking a ```json-fenced reply...\")\n    fenced = '```json\\n{\"name\": \"Chidi Eze\", \"email\": \"\"}\\n```'\n    assert parse_contact_reply(fenced) == {\"name\": \"Chidi Eze\", \"email\": \"\"}\n    print(\"  OK - empty email correctly preserved as '', not dropped\")\n\n    print(\"\\nChecking a non-JSON reply returns None...\")\n    assert parse_contact_reply(\"I couldn't find that information.\") is None\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python extract_contact.py`. You should see a clean reply parsed correctly, an empty email correctly preserved as '' rather than dropped, and a non-JSON reply correctly returning None - ending with `All checks passed.`"
        }
      ],
      "goFurther": "🛠️ Run score_candidate() on a CV that's a poor fit for your jd.txt (or write a quick fake one) - confirm the overall_score is meaningfully lower, needs_review is False (a low but CONSISTENT score isn't a review flag), and the gaps section calls out the actual mismatch."
    },
