      "number": 3,
      "title": "Batch process into Airtable",
      "time": "30 min",
      "description": "Go from \"score one CV\" to \"rank everyone automatically.\"",
      "steps": [
        {
          "instruction": "Create `airtable_write.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the HR Recruitment Screening Agent - pushes scored candidates\ninto an Airtable base.\n\"\"\"\n\nimport time\n\nimport requests\n\nAIRTABLE_RATE_LIMIT_DELAY = 0.25  # stays comfortably under Airtable's 5 req/sec limit\n\n\ndef build_record(name, email, score_data):\n    \"\"\"\n    Turns contact info and a validated score dict into the exact field\n    shape your Airtable \"Candidates\" table expects.\n\n        build_record(\"Amaka Obi\", \"amaka@example.com\", score_data)\n\n    Pure function, no network call - tested below without a real base.\n    \"\"\"\n    return {\n        \"Name\": name,\n        \"Email\": email,\n        \"Score\": score_data[\"overall_score\"],\n        \"Strengths\": \"\\n\".join(score_data.get(\"strengths\", [])),\n        \"Gaps\": \"\\n\".join(score_data.get(\"gaps\", [])),\n        \"Recommendation\": score_data.get(\"recommendation\", \"\"),\n    }\n\n\ndef push_to_airtable(base_id, table, api_key, record):\n    \"\"\"POSTs one record to the Airtable REST API.\"\"\"\n    response = requests.post(\n        f\"https://api.airtable.com/v0/{base_id}/{table}\",\n        headers={\"Authorization\": f\"Bearer {api_key}\", \"Content-Type\": \"application/json\"},\n        json={\"fields\": record},\n    )\n    response.raise_for_status()\n    time.sleep(AIRTABLE_RATE_LIMIT_DELAY)\n    return response.json()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check record-building works - no\n    # Airtable account or network call needed:  python airtable_write.py\n    score_data = {\n        \"overall_score\": 8,\n        \"strengths\": [\"Strong Python skills\", \"Led a team of 5\", \"Clear communicator\"],\n        \"gaps\": [\"Limited cloud experience\"],\n        \"recommendation\": \"Yes\",\n    }\n    record = build_record(\"Amaka Obi\", \"amaka@example.com\", score_data)\n    assert record[\"Score\"] == 8\n    assert record[\"Strengths\"] == \"Strong Python skills\\nLed a team of 5\\nClear communicator\"\n    assert record[\"Recommendation\"] == \"Yes\"\n    print(\"Built record:\", record)\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python airtable_write.py` (no Airtable account needed - this only tests record-building). You should see a record built with the score, strengths, and recommendation in the exact shape your Airtable table expects, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `batch.py` with this code, then run it on your real CVs:",
          "prompt": "\"\"\"\nStep 3 of the HR Recruitment Screening Agent (continued) - the command\nyou actually run: score every CV in a folder and push ranked results\ninto Airtable.\n\nRun it with:      python batch.py\nBlind mode:       python batch.py --blind\n\"\"\"\n\nimport os\nimport sys\n\nfrom airtable_write import build_record, push_to_airtable\nfrom blind_review import redact_pii\nfrom cv_reader import read_cvs\nfrom dotenv import load_dotenv\nfrom extract_contact import extract_contact\nfrom score import score_candidate\nfrom sdt_ai import AIError\n\nload_dotenv()\n\n\ndef process_all(folder=\"cvs\", blind=False):\n    with open(\"jd.txt\", encoding=\"utf-8\") as f:\n        jd_text = f.read()\n\n    cvs = read_cvs(folder)\n    if not cvs:\n        raise ValueError(f\"No PDF files found in '{folder}/' - add your CVs there first.\")\n\n    base_id = os.environ[\"AIRTABLE_BASE_ID\"]\n    api_key = os.environ[\"AIRTABLE_API_KEY\"]\n\n    for path, cv_text in cvs.items():\n        try:\n            # Contact info always uses the UNREDACTED text - a name and\n            # email are needed either way, and redacting them would just\n            # make the candidate impossible to follow up with.\n            contact = extract_contact(cv_text)\n            scoring_text = redact_pii(cv_text) if blind else cv_text\n            score_data = score_candidate(scoring_text, jd_text)\n        except (AIError, ValueError) as problem:\n            print(f\"Skipped {path}: {problem}\")\n            continue\n\n        record = build_record(contact[\"name\"] or \"(name not found)\", contact[\"email\"], score_data)\n        push_to_airtable(base_id, \"Candidates\", api_key, record)\n\n        flag = \" [NEEDS REVIEW]\" if score_data.get(\"needs_review\") else \"\"\n        print(f\"Processed {record['Name']}: {record['Score']}/10{flag}\")\n\n\nif __name__ == \"__main__\":\n    blind_mode = \"--blind\" in sys.argv\n    process_all(blind=blind_mode)\n",
          "verify": "Run `python batch.py`. Check Airtable - you should see one row per CV, with the Score-sorted view showing your best-fit candidates at the top, and Strengths/Gaps filled in with real text. Any candidate flagged [NEEDS REVIEW] in the console is worth opening by hand before trusting its score."
        }
